/** Default royalty-free tracks generated by scripts/make-music.mjs (each starts with a kick at t=0). */
export const MUSIC = {
  chill: { bpm: 92, file: "music/nm-chill-92.mp3", halfTime: true },
  fast: { bpm: 118, file: "music/nm-fast-118.mp3", halfTime: false },
  hyper: { bpm: 140, file: "music/nm-hyper-140.mp3", halfTime: false },
} as const;

export type Grid = { bpm: number; spb: number; halfTime: boolean };

/**
 * Where are we on the beat grid?
 * pulse: 1 on a kick, decays to 0 within ~1/4 beat (drives camera punches, light flashes, squash).
 * down:  1 on the first beat of a bar (bigger accent).
 */
export const beatInfo = (f: number, fps: number, g: Grid) => {
  const t = f / fps;
  const pos = t / g.spb;
  const beat = Math.floor(pos);
  const frac = pos - beat;
  const onKick = g.halfTime ? beat % 4 === 0 || beat % 8 === 6 : true;
  const pulse = onKick ? Math.exp(-frac * 9) : Math.exp(-frac * 9) * 0.25;
  const down = beat % 4 === 0 ? Math.exp(-frac * 6) : 0;
  return { beat, frac, pulse, down, bar: Math.floor(beat / 4) };
};
